//! Project graph: directories and files as nodes, imports as edges. Built by `scan`,
//! placed by the force `layout`, explained by `describe` (doc comments, README, or Claude).

use std::collections::HashMap;
use std::path::{Path, PathBuf};

use egui::{Pos2, Vec2};

pub mod describe;
pub mod layout;
pub mod scan;

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum NodeKind {
    Dir,
    File,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug, Default)]
pub enum DescSource {
    #[default]
    None,
    /// Module doc comment, file header comment or README.
    Heuristic,
    /// Generated by Claude (cached in `.rim/graph.json`).
    Claude,
}

#[derive(Clone, Debug)]
pub struct Node {
    pub path: PathBuf,
    /// Relative to the project root, `/`-separated; empty for the root itself.
    pub rel: String,
    pub name: String,
    pub kind: NodeKind,
    /// Lines of text (directories: sum of their files).
    pub loc: u32,
    /// Parent directory node.
    pub dir: Option<usize>,
    /// The top-level directory this node lives in (drives the colour); `None` at the root level.
    pub top: Option<usize>,
    pub depth: usize,
    pub lang: Option<&'static str>,
    pub pos: Pos2,
    pub vel: Vec2,
    pub radius: f32,
    pub pinned: bool,
    pub desc: Option<String>,
    pub desc_src: DescSource,
    /// Content hash (directories: hash of their children's hashes); keys the description cache.
    pub hash: u64,
    /// Imports that did not resolve to a project file (std, dependencies, packages).
    pub external: u32,
}

impl Node {
    pub fn is_dir(&self) -> bool {
        self.kind == NodeKind::Dir
    }
}

#[derive(Clone, Debug)]
pub struct Edge {
    pub from: usize,
    pub to: usize,
    /// How many import lines point this way (capped).
    pub weight: u8,
}

#[derive(Default, Debug)]
pub struct ProjectGraph {
    pub root: PathBuf,
    pub nodes: Vec<Node>,
    pub edges: Vec<Edge>,
    pub index: HashMap<PathBuf, usize>,
    /// Directory node indices, parents before children.
    pub dirs: Vec<usize>,
    /// Too many files: only directories are shown, with edges aggregated between them.
    pub collapsed: bool,
    pub file_count: usize,
    pub in_deg: Vec<u32>,
    pub out_deg: Vec<u32>,
}

impl ProjectGraph {
    pub fn node_at(&self, path: &Path) -> Option<usize> {
        self.index.get(path).copied()
    }

    pub fn by_rel(&self, rel: &str) -> Option<usize> {
        self.nodes.iter().position(|n| n.rel == rel)
    }

    /// Direct children of a directory node.
    pub fn children(&self, dir: usize) -> impl Iterator<Item = usize> + '_ {
        self.nodes.iter().enumerate().filter(move |(_, n)| n.dir == Some(dir)).map(|(i, _)| i)
    }

    /// Add `(from, to)` pairs, merging repeats into the edge weight and dropping self-edges.
    pub fn add_edges(&mut self, mut pairs: Vec<(usize, usize)>) {
        pairs.sort_unstable();
        for (from, to) in pairs {
            if from == to {
                continue;
            }
            match self.edges.last_mut() {
                Some(e) if e.from == from && e.to == to => e.weight = e.weight.saturating_add(1),
                _ => self.edges.push(Edge { from, to, weight: 1 }),
            }
        }
    }

    pub fn recompute_degrees(&mut self) {
        self.in_deg = vec![0; self.nodes.len()];
        self.out_deg = vec![0; self.nodes.len()];
        for e in &self.edges {
            self.out_deg[e.from] += 1;
            self.in_deg[e.to] += 1;
        }
    }

    /// Nodes this one imports, and nodes importing it.
    pub fn neighbors(&self, i: usize) -> (Vec<usize>, Vec<usize>) {
        let out = self.edges.iter().filter(|e| e.from == i).map(|e| e.to).collect();
        let inc = self.edges.iter().filter(|e| e.to == i).map(|e| e.from).collect();
        (out, inc)
    }
}

/// Node radius from its size: small files stay visible, huge ones don't dominate.
pub fn radius_for(loc: u32) -> f32 {
    3.0 + 1.6 * (1.0 + loc as f32).ln()
}

